    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(v == x for row in grid for v in row))
    pts = sorted({(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v != bg})
    if len(pts) < 3:
        return [row[:] for row in grid]
    def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lo=[]
    for p in pts:
        while len(lo)>=2 and cross(lo[-2],lo[-1],p)<=0: lo.pop()
        lo.append(p)
    hi=[]
    for p in reversed(pts):
        while len(hi)>=2 and cross(hi[-2],hi[-1],p)<=0: hi.pop()
        hi.append(p)
    hull=lo[:-1]+hi[:-1]
    out=[row[:] for row in grid]
    for r in range(h):
      for c in range(w):
        if grid[r][c] != bg: continue
        inside=True
        for a,b in zip(hull,hull[1:]+hull[:1]):
          if cross(a,b,(r,c)) < 0: inside=False; break
        if inside: out[r][c]=3
    return out
